Random & --- & 25.0 & 33.3 \\
\bottomrule
\end{tabular}}
\end{table}

\subsection{Cross-Model Transfer}
\label{sec:gen:crossmodel}

\begin{table}[t]
\centering
\small
\caption{Cross-model transfer (leave-one-out, nucleus only). Chance = 25\% / 33\% (d1--d3). d1--d3 mean 55.4\%; QWK\,=\,0.81; 94.8\% errors at $|\Delta| \leq 1$.}
\label{tab:cross_model}
\begin{tabular}{lccccc}
\toprule
Holdout & Acc & d0 & d1 & d2 & d3 \\
 & (\%) & Rec. & Rec. & Rec. & Rec. \\
\midrule
Pythia & 62.4 & 100.0 & 49.3 & 26.8 & 73.6 \\
OLMo & \textbf{69.2} & 99.3 & 75.5 & 43.3 & 58.8 \\
